tools.example:
if (app.documents.length === 0) { alert("Open a document first"); } else {
  var doc = app.activeDocument;
  $.writeln(doc.name + " " + doc.width + " x " + doc.height + " @ " + doc.resolution + " ppi");
}

var c = new SolidColor();
c.rgb.hexValue = "1A73E8";
app.foregroundColor = c;
app.activeDocument.selection.selectAll();
app.activeDocument.selection.fill(app.foregroundColor, ColorBlendMode.NORMAL, 100, false);

var saved = app.preferences.rulerUnits;
app.preferences.rulerUnits = Units.PIXELS;
try {
  var w = app.activeDocument.width.value;   // now guaranteed to be pixels
} finally {
  app.preferences.rulerUnits = saved;       // restore the user's setting
}

app.displayDialogs = DialogModes.NO;
var doc = app.open(new File("C:/in/a.psd"));   // no Missing Profile dialog
doc.flatten();
doc.close(SaveOptions.DONOTSAVECHANGES);

var major = parseInt(app.version.split(".")[0], 10);
if (major < 23) alert("This script needs Photoshop 2022 or later");
var scripts = new Folder(app.path + "/Presets/Scripts");
$.writeln(scripts.fsName);

function psName(family, style) {
  for (var i = 0; i < app.fonts.length; i++) {
    var f = app.fonts[i];
    if (f.family === family && f.style === style) return f.postScriptName;
  }
  return null;
}
var n = psName("Roboto", "Bold");
if (n) app.activeDocument.activeLayer.textItem.font = n;

for (var i = 0; i < files.length; i++) {
  processFile(files[i]);
  if (i % 10 === 0) { app.purge(PurgeTarget.HISTORYCACHES); app.refresh(); }
}
app.beep();

var files = Folder("C:/in").getFiles("*.jpg");
var o = new BatchOptions();
o.destination = BatchDestinationType.FOLDER;
o.destinationFolder = new Folder("C:/out");
o.fileNaming = [FileNamingType.DOCUMENTNAMEMIXED, FileNamingType.EXTENSIONLOWER];
o.overrideSave = true; o.suppressProfile = true; o.suppressOpen = true;
app.batch(files, "Web 1200px", "Web", o);

var picked = app.openDialog();   // returns [] when cancelled
for (var i = 0; i < picked.length; i++) {
  var d = app.open(picked[i]);
  d.flatten();
  d.saveAs(new File("C:/out/" + d.name), new JPEGSaveOptions(), true);
  d.close(SaveOptions.DONOTSAVECHANGES);
}

app.notifiers.add("Sav ", new File("C:/scripts/logSave.jsx"), "Dcmn");
app.notifiersEnabled = true;
// logSave.jsx receives arguments[0] = event ID, arguments[1] = event descriptor

var d = app.playbackParameters;
var width = 1200;
if (d.hasKey(stringIDToTypeID("width"))) width = d.getInteger(stringIDToTypeID("width"));
else if (app.playbackDisplayDialogs == DialogModes.ALL) width = Number(prompt("Width", width));
var out = new ActionDescriptor();
out.putInteger(stringIDToTypeID("width"), width);
app.playbackParameters = out;   // stored in the action step

var KEY = "com.example.resizer";
var d;
try { d = app.getCustomOptions(KEY); } catch (e) { d = new ActionDescriptor(); }
var last = d.hasKey(stringIDToTypeID("width")) ? d.getInteger(stringIDToTypeID("width")) : 1920;
var w = Number(prompt("Width", last));
d.putInteger(stringIDToTypeID("width"), w);
app.putCustomOptions(KEY, d, true);

function dump(desc) {
  for (var i = 0; i < desc.count; i++) {
    var key = desc.getKey(i);
    $.writeln(typeIDToStringID(key) + " (" + typeIDToCharID(key) + ") : " + desc.getType(key));
  }
}
var ref = new ActionReference();
ref.putEnumerated(stringIDToTypeID("layer"), stringIDToTypeID("ordinal"), stringIDToTypeID("targetEnum"));
dump(executeActionGet(ref));

var doc = app.activeDocument;
function findLayer(container, name) {
  for (var i = 0; i < container.layers.length; i++) {
    var l = container.layers[i];
    if (l.name === name) return l;
    if (l.typename === "LayerSet") { var r = findLayer(l, name); if (r) return r; }
  }
  return null;
}
var target = findLayer(doc, "logo");
if (target) doc.activeLayer = target;

var doc = app.activeDocument;
var start = doc.activeHistoryState;
try {
  riskyOperation(doc);
} catch (e) {
  doc.activeHistoryState = start;   // roll back everything
  alert("Failed: " + e.message);
}

function main() {
  var doc = app.activeDocument;
  doc.activeLayer.applyGaussianBlur(3);
  doc.activeLayer.applyUnSharpMask(80, 1, 0);
}
app.activeDocument.suspendHistory("Blur + sharpen", "main()");

var info = app.activeDocument.info;
info.author = "J. Doe";
info.copyrighted = CopyrightedType.COPYRIGHTEDWORK;
info.copyrightNotice = "(c) 2026 Studio. All rights reserved.";
info.keywords = info.keywords.concat(["campaign", "spring"]);
for (var i = 0; i < info.exif.length; i++) $.writeln(info.exif[i][0] + " = " + info.exif[i][1]);

if (ExternalObject.AdobeXMPScript == undefined) ExternalObject.AdobeXMPScript = new ExternalObject("lib:AdobeXMPScript");
var doc = app.activeDocument;
var xmp = new XMPMeta(doc.xmpMetadata.rawData);
xmp.setProperty(XMPConst.NS_DC, "description", "Hero image, spring campaign");
xmp.appendArrayItem(XMPConst.NS_DC, "subject", "hero", 0, XMPConst.ARRAY_IS_ORDERED);
doc.xmpMetadata.rawData = xmp.serialize();

app.preferences.rulerUnits = Units.PIXELS;
var doc = app.activeDocument;
while (doc.guides.length) doc.guides[0].remove();   // clear
var cols = 12, margin = 40, gutter = 20;
var colW = (doc.width.value - 2*margin - (cols-1)*gutter) / cols;
for (var c = 0; c < cols; c++) {
  var x = margin + c * (colW + gutter);
  doc.guides.add(Direction.VERTICAL, UnitValue(x, "px"));
  doc.guides.add(Direction.VERTICAL, UnitValue(x + colW, "px"));
}

var doc = app.activeDocument;
for (var i = 0; i < doc.layerComps.length; i++) {
  var comp = doc.layerComps[i];
  comp.apply();
  var o = new JPEGSaveOptions(); o.quality = 10;
  doc.saveAs(new File("C:/out/" + comp.name + ".jpg"), o, true, Extension.LOWERCASE);
}

app.preferences.rulerUnits = Units.PIXELS;
var doc = app.activeDocument;
var s = doc.colorSamplers.add([UnitValue(10,"px"), UnitValue(10,"px")]);
var c = s.color;
$.writeln("Corner pixel: " + c.rgb.red + "," + c.rgb.green + "," + c.rgb.blue);
s.remove();

var doc = app.activeDocument;
doc.autoCount(doc.channels.getByName("Alpha 1"), 128);
$.writeln("Objects: " + doc.countItems.length);

var doc = app.activeDocument;
var ms = doc.measurementScale;
ms.pixelLength = 350; ms.logicalLength = 1; ms.logicalUnits = "mm";   // 350 px per mm
doc.selection.select([[100,100],[400,100],[400,300],[100,300]]);
doc.recordMeasurements(MeasurementSource.MEASURESELECTION, ["Area", "Width", "Height"]);
// Window > Measurement Log > Export to CSV

var doc = app.activeDocument;
var report = [
  "mode: " + doc.mode,
  "depth: " + doc.bitsPerChannel,
  "profile: " + doc.colorProfileName,
  "size: " + doc.width.as("px") + "x" + doc.height.as("px") + " @ " + doc.resolution,
  "file: " + (doc.saved ? doc.fullName.fsName : "(unsaved)")
].join("\n");
alert(report);

var src = app.activeDocument;
var flat = src.duplicate("export", true);
flat.resizeImage(UnitValue(1200,"px"), null, null, ResampleMethod.BICUBICSHARPER);
flat.saveAs(new File("C:/out/export.jpg"), new JPEGSaveOptions(), true);
flat.close(SaveOptions.DONOTSAVECHANGES);
app.activeDocument = src;

var doc = app.activeDocument;
var work = doc.duplicate("flat", false);
work.mergeVisibleLayers();   // keeps transparency
work.saveAs(new File("C:/out/cutout.png"), new PNGSaveOptions(), true);
work.close(SaveOptions.DONOTSAVECHANGES);

var doc = app.activeDocument;
doc.changeMode(ChangeMode.GRAYSCALE);
var bo = new BitmapConversionOptions();
bo.method = BitmapConversionType.HALFTONESCREEN;
bo.frequency = 60; bo.angle = 45; bo.shape = BitmapHalfToneType.ROUND; bo.resolution = 600;
doc.changeMode(ChangeMode.BITMAP, bo);

var src = app.documents[0], dst = app.documents[1];
app.activeDocument = src;
src.selection.selectAll();
src.selection.copy(true);   // merged copy
app.activeDocument = dst;
var lyr = dst.paste();
lyr.name = "from " + src.name;

var doc = app.activeDocument;
doc.flatten();
var parts = doc.splitChannels();   // e.g. [name_R, name_G, name_B]
for (var i = 0; i < parts.length; i++) {
  parts[i].saveAs(new File("C:/out/" + parts[i].name + ".tif"), new TiffSaveOptions(), true);
  parts[i].close(SaveOptions.DONOTSAVECHANGES);
}

var doc = app.activeDocument;
doc.revealAll();            // bring offscreen pixels into the canvas
doc.rasterizeAllLayers();   // then all layers are editable pixels

var ps = app.activeDocument.printSettings;
ps.activePrinter = "Canon PRO-1000";
ps.colorHandling = PrintColorHandling.PHOTOSHOPMANAGED;
ps.printSpace = "Canon PRO-1000 <PT> 1/2 Photo Paper Pro Luster";
ps.renderingIntent = Intent.PERCEPTUAL;
ps.centerImage = true; ps.copies = 1;
app.activeDocument.printOneCopy();

var doc = app.activeDocument;
try {
  doc.save();
} catch (e) {
  doc.saveAs(new File(Folder.desktop + "/" + doc.name.replace(/\.[^.]+$/, "") + ".psd"), new PhotoshopSaveOptions());
}

var doc = app.activeDocument;
var hasBg = false;
try { hasBg = doc.backgroundLayer != null; } catch (e) {}
if (!hasBg) {
  var bottom = doc.artLayers[doc.artLayers.length - 1];
  bottom.isBackgroundLayer = true;   // Background from Layer
}

var doc = app.activeDocument;
doc.quickMaskMode = true;
doc.activeLayer.applyGaussianBlur(8);   // feathers the selection mask
doc.quickMaskMode = false;              // back to marching ants
